const EMBEDDED_AGENT_LISTEN_HOST = '127.0.0.1';
const EMBEDDED_AGENT_PREVIEW_HOST = 'localhost';
const OPAQUE_PREVIEW_ORIGIN = 'null';
const PREVIEW_PORT_ALLOWED_API_RE =
  /^\/api\/variants\/(?:[^/]+\/static\/|history\/[^/]+\/[^/]+\/(?:preview|site\/))/;
export const INACTIVE_VARIANTS_EVENT_HEARTBEAT_MS = 30_000;
export const RIVET_CORS_ALLOWED_HEADERS = [
  'Content-Type',
  'Authorization',
  'x-rivet-queue-token',
  EDITOR_ACCESS_TOKEN_HEADER,
];

const NO_USER_DEV_SERVER_PORT = 0;

type RivetUiBootstrap = {
  agentApplyMode: 'embedded' | 'external' | null;
  queueAccessToken: string | null;
  previewOrigin?: string | null;
};

const setNoStoreHeaders = (res: express.Response): void => {
  res.setHeader(
    'Cache-Control',
    'no-store, no-cache, must-revalidate, proxy-revalidate',
  );
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');
};

export const injectRivetUiBootstrap = (
  html: string,
  bootstrap: RivetUiBootstrap,
): string => {
  const script = `<script id="${RIVET_BOOTSTRAP_SCRIPT_ID}">window.__RIVET_BOOTSTRAP__=${escapeScriptJson(bootstrap)};</script>`;
  if (html.includes('</head>')) {
    return html.replace('</head>', `${script}</head>`);
  }
  return `${script}${html}`;
};

export const readRivetUiIndexHtml = (): string =>
  fs.readFileSync(path.join(DIST_UI_PATH, RIVET_UI_INDEX_FILENAME), 'utf8');

type InactiveVariantsEventRequest = {
  on: (event: 'close', listener: () => void) => unknown;
};

type InactiveVariantsEventResponse = {
  set: (headers: Record<string, string>) => unknown;
  flushHeaders?: () => unknown;
  write: (chunk: string) => unknown;
};

export const sendInactiveVariantsEventStream = (
  req: InactiveVariantsEventRequest,
  res: InactiveVariantsEventResponse,
): void => {
  res.set({
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache, no-transform',
    Connection: 'keep-alive',
    'X-Accel-Buffering': 'no',
  });
  res.flushHeaders?.();
  res.write('data: {"active":false}\n\n');

  const heartbeat = setInterval(() => {
    res.write(': heartbeat\n\n');
  }, INACTIVE_VARIANTS_EVENT_HEARTBEAT_MS);
  req.on('close', () => {
    clearInterval(heartbeat);
  });
};

export const resolveRivetListenHost = (
  _agentApplyMode?: 'embedded' | 'external' | null,
): string => EMBEDDED_AGENT_LISTEN_HOST;

export const resolveEmbeddedAgentUiOrigin = (port: number): string =>
  `http://${EMBEDDED_AGENT_LISTEN_HOST}:${port}`;

export const isEmbeddedAgentUiHost = (
  hostname: string,
  agentApplyMode?: 'embedded' | 'external' | null,
): boolean =>
  agentApplyMode !== 'embedded' || hostname === EMBEDDED_AGENT_LISTEN_HOST;

export const isRivetUiStaticAssetPath = (requestPath: string): boolean =>
  requestPath === '/rivet/favicon.ico' ||
  requestPath.startsWith('/rivet/assets/') ||
  requestPath.startsWith('/rivet/fonts/');

type RivetCorsOriginCheck = {
  requestOrigin?: string;
  requestHostname: string;
  requestPath: string;
  allowedOrigins: ReadonlySet<string>;
  agentApplyMode?: 'embedded' | 'external' | null;
};

export const isRivetCorsOriginAllowed = ({
  requestOrigin,
  requestHostname,
  requestPath,
  allowedOrigins,
  agentApplyMode,
}: RivetCorsOriginCheck): boolean => {
  if (!requestOrigin) {
    return true;
  }
  if (allowedOrigins.has(requestOrigin)) {
    return true;
  }
  return (
    agentApplyMode === 'embedded' &&
    requestHostname === EMBEDDED_AGENT_PREVIEW_HOST &&
    !requestPath.startsWith('/api/') &&
    !requestPath.startsWith('/rivet') &&
    requestOrigin === OPAQUE_PREVIEW_ORIGIN
  );
};

const DEV_PORT_FILENAME = '.rivet-dev-port';
const resolveDevPortFile = (): string =>
  path.join(__dirname, '..', DEV_PORT_FILENAME);

const writeDevPortFile = (port: number): void => {
  const filePath = resolveDevPortFile();
  const payload = JSON.stringify({
    port,
    pid: process.pid,
    writtenAt: new Date().toISOString(),
  });
  try {
    fs.writeFileSync(filePath, payload, 'utf8');
    log.debug(`Wrote dev-port marker at ${filePath} (port ${port})`);
  } catch (err) {
    log.debug(
      `Failed to write dev-port marker at ${filePath}: ${errorMessage(err)}`,
    );
  }
};

const removeDevPortFile = (): void => {
  const filePath = resolveDevPortFile();
  try {
    const existing = fs.readFileSync(filePath, 'utf8');
    const parsed = JSON.parse(existing) as { pid?: unknown };
    if (parsed.pid === process.pid) {
      fs.unlinkSync(filePath);
      log.debug(`Removed dev-port marker at ${filePath}`);
    }
  } catch {}
};

export type ServerOptions = Omit<CLIOptions, 'help' | 'version' | 'debug'> & {
  framework: Framework;
  telemetry?: TelemetryService;
  projectPath: string;
  projectId?: string;
  staticEntry?: string;
  styleFramework?: 'tailwind';
  tailwindConfig?: string;
  sessionBridge?: SessionBridgeService;
  variantsRuntime?: VariantsRuntime;
  agentVariantsOrchestrator?: AgentVariantsOrchestrator;
  variantRunService?: Pick<
    VariantRunService,
    'startElementVariants' | 'refineStaticPreviewBatch' | 'completeHostWork'
  >;
  mcpEditor?: string;
  agentApplyMode?: 'embedded' | 'external';
  skipProcessHandlers?: boolean;
  cliShutdown?: () => void;
  restartArgs?: string[];
  rivetPort?: number;
  previewPort?: number;
  userHost?: string;
  beforeShutdown?: () => Promise<void>;
  resolveLibraryOrigin?: () => string | undefined;
  resolveProjectName?: (projectPath: string) => string | undefined;
  createLibraryViewUrl?: (
    view: 'projects' | 'references',
  ) => Promise<string | null>;
};

export type ServerHandle = {
  editorUrl: string;
  close: () => Promise<void>;
};

export const runServerShutdownTasks = async (options: {
  beforeShutdown?: () => Promise<void>;
  telemetry?: Pick<TelemetryService, 'shutdown'>;
  featureFlags?: { shutdown: () => Promise<void> };
}): Promise<void> => {
  await options.beforeShutdown?.();
  await options.telemetry?.shutdown();
  await options.featureFlags?.shutdown();
};

export const startServer = async (
  options: ServerOptions,
): Promise<ServerHandle> => {
  const {
    userPort,
    userHost,
    telemetry,
    projectPath,
    framework,
    staticEntry,
    sessionBridge,
    mcpEditor,
    skipProcessHandlers,
  } = options;
  const agentApplyMode = options.agentApplyMode;
  const editorAccessToken = createEditorAccessToken();
  const startedAt = new Date().toISOString();

  const userPortWithFallback = userPort ?? DEFAULT_USER_PORT;
  const userHostWithFallback = userHost ?? 'localhost';
  const hasUserDevServer =
    typeof userPort === 'number' && Number.isInteger(userPort) && userPort > 0;
  const queueAccessToken =
    sessionBridge && agentApplyMode === 'embedded'
      ? randomBytes(QUEUE_ACCESS_TOKEN_BYTES).toString('base64url')
      : null;
  const variantsOrchestrator =
    options.variantsRuntime?.orchestrator ?? options.agentVariantsOrchestrator;
  await variantsOrchestrator?.loadDirectionRefs();
  const inlineStartTracker = createInlineStartTracker();
  const runtimeAdmission = new RuntimeAdmission(RIVET_VERSION);
  const variantsBridge = options.variantsRuntime?.bridge ?? sessionBridge;
  const variantRunService =
    options.variantsRuntime?.runService ?? options.variantRunService;
  const variantHistory = variantsOrchestrator
    ? (options.variantsRuntime?.history ?? new VariantHistoryService())
    : null;
  const historyReplay =
    variantsOrchestrator && variantHistory
      ? new HistoryReplayService({
          history: variantHistory,
          devServers: variantsOrchestrator.devServerManager,
          switchPreviewPort: variantsBridge
            ? (port) => variantsBridge.switchPreviewPort(port)
            : undefined,
        })
      : null;

  if (process.env.SENTRY_DSN && getTelemetryMode() === 'full') {
    Sentry.init({
      dsn: process.env.SENTRY_DSN,
      environment: process.env.NODE_ENV ?? 'development',
    });
  }

  let staticService: StaticFileService | null = null;
  if (framework === 'static') {
    const entryPoint = staticEntry || 'index.html';
    staticService = new StaticFileService(projectPath, entryPoint);
  }

  let listenPort = options.rivetPort ?? DEFAULT_PORT;
  const previewPort = options.previewPort;
  let previewOrigin =
    previewPort !== undefined
      ? `http://${EMBEDDED_AGENT_LISTEN_HOST}:${previewPort}`
      : `http://${EMBEDDED_AGENT_PREVIEW_HOST}:${listenPort}`;
  let userDevProxy: ReturnType<typeof createUserDevServerProxy> | null = null;
  const app = express();
  const requireEditorAccess = authenticateEditor(editorAccessToken);
  app.use(EDITOR_ACCOUNT_PATHS, requireEditorAccess);
  const editorHost = (): string =>
    `${EMBEDDED_AGENT_LISTEN_HOST}:${listenPort}`;
  const isPreviewRequest = (req: express.Request): boolean =>
    req.headers.host === new URL(previewOrigin).host &&
    (previewPort === undefined || req.socket.localPort === previewPort);
  const rejectRequest = ({
    req,
    res,
    reason,
  }: {
    req: express.Request;
    res: express.Response;
    reason: RequestRejectionReason;
  }): void => {
    log.warn(`Rejected ${req.method} ${req.path} with 403: ${reason}`);
    telemetry?.trackRequestRejected(reason);
    res.sendStatus(403);
  };
  app.use((req, res, next) => {
    const requestHost = req.headers.host;
    const isEditorRequest =
      requestHost === editorHost() && req.socket.localPort === listenPort;
    if (!isEditorRequest && !isPreviewRequest(req)) {
      rejectRequest({ req, res, reason: 'host_not_allowed' });
      return;
    }
    next();
  });
  const corsOrigins = new Set<string>([
    resolveEmbeddedAgentUiOrigin(listenPort),
  ]);
  const rawCorsOrigins = process.env.RIVET_CORS_ORIGINS;
  if (rawCorsOrigins) {
    rawCorsOrigins
      .split(',')
      .map((origin) => origin.trim())
      .filter((origin) => origin.length > 0)
      .forEach((origin) => corsOrigins.add(origin));
  }
  app.use((req, res, next) => {
    cors({
      origin: (origin, callback) => {
        callback(
          null,
          isRivetCorsOriginAllowed({
            requestOrigin: origin,
            requestHostname: req.hostname,
            requestPath: req.path,
            allowedOrigins: corsOrigins,
            agentApplyMode,
          }),
        );
      },
      credentials: true,
      methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
      allowedHeaders: RIVET_CORS_ALLOWED_HEADERS,
    })(req, res, next);
  });

  app.use((req, res, next) => {
    if (!isPreviewRequest(req)) {
      next();
      return;
    }
    if (req.headers[EDITOR_ACCESS_TOKEN_HEADER]) {
      rejectRequest({ req, res, reason: 'editor_token_on_preview' });
      return;
    }
    const isAppApi =
      req.path.toLowerCase().startsWith('/api/') &&
      !PREVIEW_PORT_ALLOWED_API_RE.test(req.path.toLowerCase());
    const isEditorUi =
      req.path.toLowerCase() === '/rivet' ||
      req.path.toLowerCase().startsWith('/rivet/');
    if (isEditorUi || /^\/api\/git(?:\/|$)/i.test(req.path)) {
      res.status(404).end();
      return;
    }
    if (isAppApi) {
      if (userDevProxy) {
        userDevProxy.middleware(req, res, (error?: unknown) => {
          if (error) {
            next(error);
            return;
          }
          res.sendStatus(404);
        });
      } else {
        res.sendStatus(404);
      }
      return;
    }
    next();
  });

  app.use(authenticateEditorApi(editorAccessToken));

  app.use('/api/telemetry', createTelemetryRouter(telemetry));
  const jsonBodyParser = express.json({ limit: '50mb' });
  app.use(jsonBodyParser);

  app.use((req, res, next) => {
    log.debug(`${req.method} ${req.originalUrl}`);
    next();
  });

  const uiStaticOptions: Parameters<typeof express.static>[1] = {
    setHeaders: (res: express.Response, filePath: string) => {
      if (filePath.endsWith('.html')) {
        setNoStoreHeaders(res);
      } else if (process.env.NODE_ENV !== 'production') {
        setNoStoreHeaders(res);
      } else {
        res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
      }
    },
  };
  const sendRivetUiIndex = (
    req: express.Request,
    res: express.Response,
  ): void => {
    if (!isEmbeddedAgentUiHost(req.hostname, 'embedded')) {
      res.redirect(
        302,
        `${resolveEmbeddedAgentUiOrigin(listenPort)}${req.originalUrl}`,
      );
      return;
    }
    setNoStoreHeaders(res);
    const libraryOrigin = options.resolveLibraryOrigin?.();
    res.setHeader(
      'Content-Security-Policy',
      `frame-ancestors 'self'${libraryOrigin ? ` ${new URL(libraryOrigin).origin}` : ''}`,
    );
    res.type('html').send(
      injectRivetUiBootstrap(readRivetUiIndexHtml(), {
        agentApplyMode: agentApplyMode ?? null,
        queueAccessToken,
        previewOrigin,
      }),
    );
  };
  const serveEditorAssets = (directory: string): express.RequestHandler => {
    const serve = express.static(directory, uiStaticOptions);
    return (req, res, next) =>
      isPreviewRequest(req) ? next() : serve(req, res, next);
  };
  app.use('/assets', serveEditorAssets(path.join(DIST_UI_PATH, 'assets')));
  app.use(
    '/rivet/assets',
    serveEditorAssets(path.join(DIST_UI_PATH, 'assets')),
  );
  app.use('/fonts', serveEditorAssets(path.join(DIST_UI_PATH, 'fonts')));
  app.use('/rivet/fonts', serveEditorAssets(path.join(DIST_UI_PATH, 'fonts')));
  app.get('/favicon.ico', (_req, res) => {
    res.sendFile('favicon.ico', { root: DIST_UI_PATH });
  });
  app.get('/rivet/favicon.ico', (_req, res) => {
    res.sendFile('favicon.ico', { root: DIST_UI_PATH });
  });
  app.get(/^\/rivet\/library(?:\/.*)?$/, (req, res) => {
    const resolvedLibraryOrigin = options.resolveLibraryOrigin?.();
    if (!resolvedLibraryOrigin) {
      res.sendStatus(404);
      return;
    }
    res.redirect(
      302,
      `${new URL(resolvedLibraryOrigin).origin}${req.path}`,
    );
  });
  app.get(/^\/rivet(?:\/.*)?$/, (req, res, next) => {
    if (isRivetUiStaticAssetPath(req.path)) {
      next();
      return;
    }
    sendRivetUiIndex(req, res);
  });
  log.info(`Serving UI assets from: ${DIST_UI_PATH}`);

  if (framework === 'static' && !hasUserDevServer) {
    app.get('/', (req, res, next) => {
      if (isPreviewRequest(req)) {
        next();
        return;
      }
      log.debug(`${framework} mode - serving Rivet at root`);
      sendRivetUiIndex(req, res);
    });
    app.get(/^\/rivet(?:\/.*)?$/, (req, res, next) => {
      if (isRivetUiStaticAssetPath(req.path)) {
        next();
        return;
      }
      const rest = req.path.slice('/rivet'.length);
      const target = rest && rest !== '/' ? rest : '/';
      const queryStart = req.originalUrl.indexOf('?');
      const search = queryStart >= 0 ? req.originalUrl.slice(queryStart) : '';
      res.redirect(302, `${target}${search}`);
    });
  }

  const getBearerTokenFromHeader = (
    authorizationHeader: unknown,
  ): string | undefined => {
    if (typeof authorizationHeader !== 'string') {
      return undefined;
    }
    if (!authorizationHeader.startsWith('Bearer ')) {
      return undefined;
    }
    const token = authorizationHeader.slice('Bearer '.length).trim();
    return token.length > 0 ? token : undefined;
  };

  app.use((req, _res, next) => {
    const headerToken = getBearerTokenFromHeader(req.headers.authorization);
    if (!headerToken) {
      next();
      return;
    }
    runWithRequestAuthContext({ token: headerToken }, () => {
      next();
    });
  });

  app.use(
    '/api',
    createIntegrationsRouter({ openExternalUrl: openInSystemBrowser }),
  );
  app.use('/api', createReferenceProfilesRouter());
  void pruneWorktrees(projectPath);
  app.use('/api/git', (_req, res) => res.sendStatus(404));

  app.use('/api', createSupportRouter(telemetry));

  app.use((req, res, next) => {
    const isPreviewPath =
      req.path.toLowerCase().startsWith('/static') ||
      req.path.toLowerCase().startsWith('/__rivet/preview/') ||
      PREVIEW_PORT_ALLOWED_API_RE.test(req.path.toLowerCase());
    if (!isPreviewRequest(req) && isPreviewPath) {
      if (req.headers[EDITOR_ACCESS_TOKEN_HEADER]) {
        rejectRequest({ req, res, reason: 'editor_token_on_preview' });
        return;
      }
      res.redirect(302, `${previewOrigin}${req.originalUrl}`);
      return;
    }
    next();
  });

  if (staticService) {
    app.use(
      createStaticRoutes(staticService, projectPath, {
        isPreviewBridgeEnabled: true,
        get expectedPreviewParentOrigin() {
          return resolveEmbeddedAgentUiOrigin(listenPort);
        },
      }),
    );
    log.info('Static routes mounted at /static');
  }

  app.get('/api/health', (req, res) => {
    let originalPreviewPath: string | null = null;
    if (staticService) {
      const entryPath = path.join(
        staticService.getBasePath(),
        staticService.getEntryFileName(),
      );
      if (fs.existsSync(entryPath)) originalPreviewPath = '/static/';
    } else if (hasUserDevServer) {
      originalPreviewPath = '/__rivet/preview/base/';
    }
    res.json({
      status: 'healthy',
      projectPath,
      pid: process.pid,
      channel: installationChannel(),
      rivetVersion: RIVET_VERSION,
      pluginName: getPluginName(),
      telemetryMode: getTelemetryMode(),
      timestamp: new Date().toISOString(),
      framework,
      ports: {
        rivet: listenPort,
        userDevServer: userPortWithFallback,
      },
      originalPreviewPath,
    });
  });

  app.get('/api/feature-flags', async (req, res) => {
    const configManager = getConfigManager();
    const featureFlagUserKey = getConfigFeatureFlagUserKey({
      headers: req.headers,
      fallbackEmail: configManager.getEmail(),
    });
    const featureFlags = await getFeatureFlags({ userKey: featureFlagUserKey });
    res.json({ featureFlags });
  });

  app.get('/api/config', async (_req, res) => {
    const configManager = getConfigManager();
    const livePath = sessionBridge?.getProjectPath() ?? projectPath;
    const initiator = sessionBridge?.getSessionRuntimeInfo().sessionInitiator;
    res.json({
      agentModeAvailable: configManager.isAuthenticated(),
      email: configManager.getEmail(),
      userId: configManager.getUserId(),
      name: configManager.getDisplayName(),
      isMCPSession: sessionBridge?.isActive() ?? false,
      mcpEditor:
        mcpEditor ?? (initiator?.kind === 'agent' ? initiator.agent : null),
      agentApplyMode: sessionBridge?.isActive()
        ? (agentApplyMode ?? 'external')
        : null,
      projectPath: livePath,
      projectName:
        options.resolveProjectName?.(livePath) ?? path.basename(livePath),
      projectId: options.projectId ?? null,
      libraryOrigin: options.resolveLibraryOrigin?.() ?? null,
    });
  });

  app.post(
    '/api/library/browser-launches',
    express.urlencoded({ extended: false }),
    async (req, res) => {
      if (!isLocalBrowserRequest(req))
        return rejectRequest({ req, res, reason: 'origin_not_allowed' });
      const view = req.body?.view;
      if (view !== 'projects' && view !== 'references')
        return res.sendStatus(400);
      try {
        const url = await options.createLibraryViewUrl?.(view);
        if (!url) return res.sendStatus(503);
        return res.json({ url } satisfies LibraryViewLaunchResponse);
      } catch (error) {
        log.error('Could not open the project library', error);
        return res.sendStatus(503);
      }
    },
  );

  app.use('/api', createInstallRefRouter());
  app.use(
    '/api',
    createSignInLaunchRouter({
      openExternalUrl: openInSystemBrowser,
      config: getConfigManager(),
    }),
  );
  app.use('/api', createAccountRouter(telemetry));
  app.use('/api', createPreferencesRouter());

  if (sessionBridge) {
    app.use(
      '/api/mcp',
      createMCPRouter(sessionBridge, options.telemetry, variantsOrchestrator, {
        queueAccessToken: queueAccessToken ?? undefined,
      }),
    );
    log.info('MCP bridge routes mounted at /api/mcp');

    app.use(
      '/api/cli',
      createCliRouter({
        bridge: sessionBridge,
        orchestrator: variantsOrchestrator,
        rivetPort: listenPort,
        queueAccessToken,
        onShutdown: options.cliShutdown,
        beforeUpgrade: () =>
          options.variantsRuntime?.runService.interruptWorkers(),
        inlineStart: inlineStartTracker,
        admission: runtimeAdmission,
        restartArgs: options.restartArgs,
      }),
    );
    log.info('CLI control routes mounted at /api/cli');
  }

  if (variantsOrchestrator) {
    app.use(
      '/api',
      createAgentVariantsRouter(
        variantsOrchestrator,
        variantsBridge,
        telemetry,
        variantHistory ?? undefined,
        undefined,
        variantRunService,
        historyReplay ?? undefined,
        {
          isEnabled: true,
          resolveLibraryOrigin: options.resolveLibraryOrigin,
          get expectedParentOrigin() {
            return resolveEmbeddedAgentUiOrigin(listenPort);
          },
        },
        inlineStartTracker,
        runtimeAdmission,
      ),
    );
    log.info('agent-variants routes mounted at /api/variants');
  } else {
    app.get('/api/variants/active', (_req, res) => {
      res.json({ active: false });
    });
    app.get('/api/variants/events', (req, res) => {
      sendInactiveVariantsEventStream(req, res);
    });
  }

  if (framework !== 'static' || hasUserDevServer || variantsBridge) {
    const proxyUserPort =
      framework === 'static' && !hasUserDevServer
        ? NO_USER_DEV_SERVER_PORT
        : userPortWithFallback;
    userDevProxy = createUserDevServerProxy(
      proxyUserPort,
      userHostWithFallback,
      {
        isPreviewBridgeEnabled: true,
        get expectedPreviewParentOrigin() {
          return resolveEmbeddedAgentUiOrigin(listenPort);
        },
        resolveVariantPreviewPort: (sessionId, variantId, options) => {
          if (options?.source === 'history') {
            return historyReplay?.getPort(sessionId, variantId) ?? null;
          }
          const port = variantsOrchestrator?.resolveDevServerPortForPreview(
            sessionId,
            variantId,
          );
          if (typeof port === 'number') return port;
          return historyReplay?.getPort(sessionId, variantId) ?? null;
        },
      },
    );

    variantsBridge?.registerVariantTargetSetter(userDevProxy.setVariantTarget);

    app.use((req, res, next) => {
      if (!isPreviewRequest(req)) {
        if (req.path.toLowerCase().startsWith('/api/')) {
          res.sendStatus(404);
          return;
        }
        if (req.headers[EDITOR_ACCESS_TOKEN_HEADER]) {
          rejectRequest({ req, res, reason: 'editor_token_on_preview' });
          return;
        }
        res.redirect(302, `${previewOrigin}${req.originalUrl}`);
        return;
      }
      if (req.headers[EDITOR_ACCESS_TOKEN_HEADER]) {
        rejectRequest({ req, res, reason: 'editor_token_on_preview' });
        return;
      }
      next();
    });
    app.get('/{*any}', userDevProxy.middleware);
    app.post('/{*any}', userDevProxy.middleware);
    app.put('/{*any}', userDevProxy.middleware);
    app.delete('/{*any}', userDevProxy.middleware);
    app.patch('/{*any}', userDevProxy.middleware);

    log.info(
      proxyUserPort > 0
        ? `Proxying all unmatched routes to user dev server on ${userHostWithFallback}:${proxyUserPort}`
        : 'Proxying variant previews without a base user dev server',
    );
  } else {
    log.info(`${framework} mode - skipping proxy setup`);
  }

  if (process.env.SENTRY_DSN && getTelemetryMode() === 'full') {
    Sentry.setupExpressErrorHandler(app);
  }

  app.use(
    (
      err: Error,
      req: express.Request,
      res: express.Response,

      _next: express.NextFunction,
    ) => {
      const requestAborted =
        (err as { code?: string; type?: string }).code === 'ECONNABORTED' ||
        (err as { code?: string; type?: string }).type === 'request.aborted';
      if (requestAborted) {
        log.debug('Request aborted by client');
        return;
      }
      log.error('Unhandled route error:', err);
      telemetry?.captureException(err, 'express_error_handler');
      if (!res.headersSent) {
        res.status(500).json({
          error: 'Internal server error',
          details: err.message,
        });
      }
    },
  );

  const activeSockets = new Set<Socket>();

  let handshakeApplyMode: ServerHandshake['applyMode'] = 'none';
  if (sessionBridge) {
    handshakeApplyMode = agentApplyMode === 'embedded' ? 'embedded' : 'none';
  }
  const advertiseCliHandshake = (): void => {
    try {
      writeHandshake({
        version: CLI_HANDSHAKE_VERSION,
        pid: process.pid,
        rivetPort: listenPort,
        projectPath,
        startedAt,
        sessionId: sessionBridge?.getSessionId() ?? null,
        applyMode: handshakeApplyMode,
        queueAccessToken,
        rivetVersion: RIVET_VERSION,
        pluginName: getPluginName(),
        telemetryMode: getTelemetryMode(),
      });
    } catch (err) {
      log.debug('Failed to write CLI handshake (non-fatal)', err);
    }
  };
  const retireCliHandshake = (): void => {
    removeHandshake(projectPath, process.pid);
    removeEditorSession(
      { pid: process.pid, port: listenPort, projectPath, startedAt },
      editorAccessToken,
    );
  };

  const httpServer = await new Promise<ReturnType<typeof app.listen>>(
    (resolve, reject) => {
      const listenHost = resolveRivetListenHost(agentApplyMode);
      const server = app.listen(listenPort, listenHost, (error?: Error) => {
        if (error) {
          reject(error);
          return;
        }
        log.info(
          `🎨 Rivet server running on http://${listenHost}:${listenPort}`,
        );
        listenPort = (server.address() as { port: number }).port;
        if (previewPort === undefined)
          previewOrigin = `http://${EMBEDDED_AGENT_PREVIEW_HOST}:${listenPort}`;
        corsOrigins.add(resolveEmbeddedAgentUiOrigin(listenPort));
        try {
          writeEditorSession({
            pid: process.pid,
            port: listenPort,
            projectPath,
            token: editorAccessToken,
            startedAt,
          });
        } catch (error) {
          server.close(() => reject(error));
          return;
        }
        writeDevPortFile(listenPort);
        advertiseCliHandshake();
        resolve(server);
      });

      server.on('error', (err: Error & { code?: string }) => {
        reject(err);
      });

      server.on('connection', (socket: Socket) => {
        activeSockets.add(socket);
        socket.on('close', () => activeSockets.delete(socket));
      });

      server.on('upgrade', (req, socket, head) => {
        const pathname = req.url?.split('?')[0] ?? '';

        log.debug(`WebSocket upgrade request for: ${pathname}`);

        const proxyUpgrade = (
          userDevProxy?.middleware as
            | {
                upgrade?: (
                  req: unknown,
                  socket: unknown,
                  head: unknown,
                ) => void;
              }
            | undefined
        )?.upgrade;
        if (proxyUpgrade) {
          log.debug('Proxying upgrade to user dev server for HMR');
          proxyUpgrade(req, socket as Socket, head);
          return;
        }

        log.warn(`No handler for WebSocket upgrade: ${pathname}`);
        socket.destroy();
      });
    },
  );

  let previewHttpServer: HttpServer | null = null;
  if (previewPort !== undefined) {
    try {
      previewHttpServer = await new Promise<HttpServer>((resolve, reject) => {
        const pServer = createHttpServer(app);
        pServer.on('error', reject);
        pServer.on('connection', (socket: Socket) => {
          activeSockets.add(socket);
          socket.on('close', () => activeSockets.delete(socket));
        });
        pServer.on('upgrade', (req, socket, head) => {
          const proxyUpgrade = (
            userDevProxy?.middleware as
              | {
                  upgrade?: (
                    req: unknown,
                    socket: unknown,
                    head: unknown,
                  ) => void;
                }
              | undefined
          )?.upgrade;
          if (proxyUpgrade) {
            proxyUpgrade(req, socket as Socket, head);
            return;
          }
          socket.destroy();
        });
        pServer.listen(previewPort, EMBEDDED_AGENT_LISTEN_HOST, () => {
          log.info(
            `🔒 Rivet isolated preview origin on http://${EMBEDDED_AGENT_LISTEN_HOST}:${previewPort}`,
          );
          resolve(pServer);
        });
      });
    } catch (error) {
      removeDevPortFile();
      retireCliHandshake();
      await new Promise<void>((resolve) => {
        httpServer.close(() => resolve());
        for (const socket of activeSockets) socket.destroy();
      });
      throw error;
    }
  }

  if (!skipProcessHandlers) {
    const shutdownAndExit = async (code: number) => {
      log.info('Server shutting down, cleaning up...');
      cleanupOrphanedWorktrees();
      const results = await Promise.allSettled([
        options.beforeShutdown?.(),
        telemetry?.shutdown(),
        getFeatureFlagService().shutdown(),
      ]);
      const labels = ['shutdown hook', 'telemetry', 'feature flags'];
      for (let i = 0; i < results.length; i++) {
        if (results[i].status === 'rejected') {
          log.error(
            `Failed to cleanup ${labels[i]}:`,
            (results[i] as PromiseRejectedResult).reason,
          );
        }
      }
      removeHandshake(projectPath, process.pid);
      removeEditorSession(
        { pid: process.pid, port: listenPort, projectPath, startedAt },
        editorAccessToken,
      );
      process.exit(code);
    };

    process.on('SIGINT', () => shutdownAndExit(0));
    process.on('SIGTERM', () => shutdownAndExit(0));

    process.on('uncaughtException', (err) => {
      log.error('Uncaught exception:', err);
      telemetry?.captureException(err, 'uncaught_exception');
      shutdownAndExit(1);
    });

    process.on('unhandledRejection', (reason) => {
      log.error('Unhandled rejection:', reason);
      telemetry?.captureException(reason, 'unhandled_rejection');
      shutdownAndExit(1);
    });
  }

  return {
    editorUrl: createEditorUrl({
      port: (httpServer.address() as { port: number }).port,
      token: editorAccessToken,
    }),
    close: () =>
      new Promise<void>((resolve, reject) => {
        removeDevPortFile();
        retireCliHandshake();
        previewHttpServer?.close();
        httpServer.close((err) => {
          if (err) {
            reject(err);
            return;
          }
          void (async () => {
            await runServerShutdownTasks({
              beforeShutdown: options.beforeShutdown,
              telemetry,
            });
            resolve();
          })();
        });
        for (const socket of activeSockets) {
          socket.destroy();
        }
      }),
  };
};
